script:
:root {
  --f-toast-bg: #ffffff;
  --f-toast-border: #f3f4f6;
  --f-toast-shadow:
    0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --f-toast-text-title: #111827;
  --f-toast-text-body: #4b5563;
  --f-toast-close: #9ca3af;
  --f-toast-close-hover: #4b5563;

  --f-icon-success: #16a34a;
  --f-icon-error: #dc2626;
  --f-icon-info: #2563eb;
  --f-icon-warning: #d97706;
  --f-dialog-backdrop: rgba(17, 24, 39, 0.4);
  --f-dialog-bg: #ffffff;
  --f-dialog-text-title: #111827;
  --f-dialog-text-body: #4b5563;
  --f-dialog-border: #f3f4f6;

  --f-btn-bg: #f3f4f6;
  --f-btn-text: #1f2937;
  --f-btn-hover: #e5e7eb;

  --f-btn-solid-bg: #1f2937;
  --f-btn-solid-text: #ffffff;
  --f-btn-solid-hover: #111827;

  --f-btn-red-bg: #dc2626;
  --f-btn-red-text: #ffffff;
  --f-btn-red-hover: #b91c1c;
}

/* ================== Toast styles ==================== */

.frappe-toast-wrapper {
  position: fixed;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.5rem;
  padding: 1.5rem;
  pointer-events: none;
  box-sizing: border-box;
}

/* Positioning modifiers */
.frappe-pos-top-right {
  top: 0;
  right: 0;
}
.frappe-pos-top-left {
  top: 0;
  left: 0;
}
.frappe-pos-top-center {
  top: 0;
  left: 50%;
  transform: translateX(-50%);
}
.frappe-pos-bottom-right {
  bottom: 0;
  right: 0;
}
.frappe-pos-bottom-left {
  bottom: 0;
  left: 0;
}
.frappe-pos-bottom-center {
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
}

/* Main Card */
.frappe-toast {
  display: flex;
  align-items: flex-start;
  padding: 0.75rem;
  background-color: var(--f-toast-bg);
  box-shadow: var(--f-toast-shadow);
  border-radius: 0.5rem;
  border: 1px solid var(--f-toast-border);
  pointer-events: auto;
  max-width: 350px;
  width: max-content;

  transition:
    transform 0.3s ease,
    opacity 0.3s ease;
  transform: translateY(1rem) scale(0.95);
  opacity: 0;
}

.frappe-toast.frappe-toast-show {
  transform: translateY(0) scale(1);
  opacity: 1;
}

/* Icon Styling */
.frappe-toast-icon {
  flex-shrink: 0;
  margin-right: 0.5rem;
}
.frappe-toast-icon svg {
  width: 1.25rem;
  height: 1.25rem;
  stroke-width: 2;
}
.f-icon-success {
  color: var(--f-icon-success);
}
.f-icon-error {
  color: var(--f-icon-error);
}
.f-icon-info {
  color: var(--f-icon-info);
}
.f-icon-warning {
  color: var(--f-icon-warning);
}

/* Content & Typography */
.frappe-toast-content {
  flex: 1;
  min-width: 0;
}
.frappe-toast-title {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--f-toast-text-title);
  line-height: 1.25rem;
}
.frappe-toast-text {
  font-size: 0.875rem;
  color: var(--f-toast-text-body);
  line-height: 1.25rem;
}

.frappe-toast-content.no-title .frappe-toast-text {
  margin-top: 0;
  font-weight: 500;
  color: var(--f-toast-text-title);
}

/* Close Button */
.frappe-toast-close {
  flex-shrink: 0;
  margin-left: 1rem;
  color: var(--f-toast-close);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: color 0.2s ease;
  display: inline-flex;
  border-radius: 0.25rem;
}
.frappe-toast-close:hover {
  color: var(--f-toast-close-hover);
}
.frappe-toast-close:focus {
  outline: 2px solid var(--f-toast-border);
}
.frappe-toast-close svg {
  width: 1.25rem;
  height: 1.25rem;
  stroke-width: 1.5;
}

/* ================== Dialog styles ==================== */

/* Prevent body scroll when dialog is open */
body.frappe-dialog-open {
  overflow: hidden;
}

/* Backdrop */
.frappe-dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--f-dialog-backdrop);
  backdrop-filter: blur(4px);
  padding: 1rem;

  opacity: 0;
  transition: opacity 0.2s ease-out;
}
.frappe-dialog-backdrop.fd-show {
  opacity: 1;
}

/* Modal Container */
.frappe-dialog-panel {
  background-color: var(--f-dialog-bg);
  border-radius: 0.75rem;
  box-shadow:
    0 20px 25px -5px rgba(0, 0, 0, 0.1),
    0 10px 10px -5px rgba(0, 0, 0, 0.04);
  width: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  font-family: inherit;

  transform: scale(0.95);
  transition:
    transform 0.2s ease-out,
    opacity 0.2s ease-out;
  opacity: 0;
}
.frappe-dialog-backdrop.fd-show .frappe-dialog-panel {
  transform: scale(1);
  opacity: 1;
}

/* Width modifiers */
.fd-size-sm {
  max-width: 24rem;
}
.fd-size-md {
  max-width: 28rem;
}
.fd-size-lg {
  max-width: 32rem;
}
.fd-size-xl {
  max-width: 36rem;
}
.fd-size-2xl {
  max-width: 42rem;
}

/* Layout Sections */
.frappe-dialog-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.25rem 0.5rem 1.25rem;
}
.frappe-dialog-title {
  margin: 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--f-dialog-text-title);
  line-height: 1.75rem;
}

.frappe-dialog-close {
  background: transparent;
  border: none;
  color: #9ca3af;
  cursor: pointer;
  padding: 0.25rem;
  border-radius: 0.375rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    background-color 0.2s,
    color 0.2s;
}
.frappe-dialog-close:hover {
  background-color: var(--f-btn-bg);
  color: var(--f-dialog-text-body);
}
.frappe-dialog-close svg {
  width: 1.25rem;
  height: 1.25rem;
}

/* Body */
.frappe-dialog-body {
  padding: 0.5rem 1.25rem 1.25rem 1.25rem;
  color: var(--f-dialog-text-body);
  font-size: 0.875rem;
  line-height: 1.5;
  overflow-y: auto;
  max-height: calc(100vh - 12rem);
}
.frappe-dialog-body p {
  margin: 0;
}
.frappe-dialog-error {
  margin-top: 0.75rem;
  color: var(--f-btn-red-text);
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  padding: 0.5rem 0.75rem;
  border-radius: 0.375rem;
  font-size: 0.875rem;
}

/* Footer / Actions */
.frappe-dialog-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 0 1rem 1.25rem;
}

/* Button Styles*/
.frappe-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 420;
  padding: 0 0.5rem;
  border-radius: 0.5rem;
  border: 1px solid transparent;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
  line-height: 1.5rem;
  outline: none;
  letter-spacing: 0.02em;
}
.frappe-btn:focus-visible {
  box-shadow:
    0 0 0 2px #fff,
    0 0 0 4px #1f2937;
}

/* Variants */
.frappe-btn-default {
  background-color: #ffffff;
  border-color: #d1d5db;
  color: #374151;
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}
.frappe-btn-default:hover {
  background-color: #f9fafb;
}

.frappe-btn-solid {
  background-color: var(--f-btn-solid-bg);
  color: var(--f-btn-solid-text);
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}
.frappe-btn-solid:hover {
  background-color: var(--f-btn-solid-hover);
}

.frappe-btn-red-solid {
  background-color: var(--f-btn-red-bg);
  color: var(--f-btn-red-text);
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}
.frappe-btn-red-solid:hover {
  background-color: var(--f-btn-red-hover);
}

.hide-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.form-row {
  display: flex;
  gap: 1rem;
}

.hide {
  display: none !important;
}

@media (max-width: 640px) {
  .form-row {
    flex-direction: column;
  }
}

@media (max-width: 767px) {
  #sidebar {
    display: none !important;
  }
  #bottom-menu {
    display: flex !important;
  }
}

@media (min-width: 767px) {
  #navbar-logo {
    display: none !important;
  }
  #bottom-menu {
    display: none !important;
  }
}
